import{_ as n,o as t,c as a,a3 as i}from"./chunks/framework.BZKbe9n2.js";const g=JSON.parse('{"title":"Wartung","description":"","frontmatter":{},"headers":[],"relativePath":"de/administration/maintenance.md","filePath":"de/administration/maintenance.md"}'),r={name:"de/administration/maintenance.md"};function s(l,e,d,o,h,u){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="wartung" tabindex="-1">Wartung <a class="header-anchor" href="#wartung" aria-label="Permalink to &quot;Wartung&quot;">​</a></h1><h2 id="systempflege" tabindex="-1">Systempflege <a class="header-anchor" href="#systempflege" aria-label="Permalink to &quot;Systempflege&quot;">​</a></h2><p>Die Systempflege (<strong>Einstellungen</strong>, Administratoren) läuft in der Vorgabe täglich um 03:00 in der Zeitzone der Installation; Administratoren können den Zeitplan (aus, täglich, wöchentlich), die Schonfrist und die Sicherheitsgrenze ändern oder nur melden lassen. Sie</p><ul><li>löscht verwaiste Dateien und Reste abgebrochener Übertragungen im verwalteten Ordner der Bibliothek, nach einer Schonfrist (Vorgabe 24 Stunden);</li><li>listet verwaltete Originale, deren Datei fehlt (sie ändert sie nie).</li></ul><p>Referenzierte Dateien werden nie angefasst. Würde ein Lauf mehr löschen als die Sicherheitsgrenze (Vorgabe 1 % der verwalteten Dateien, mindestens 10), löscht er nichts und wartet auf deine Bestätigung – das schützt vor einer Datenbank aus einer älteren Sicherung oder einer falsch eingehängten Bibliothek.</p><h2 id="erkennung-und-metadaten" tabindex="-1">Erkennung und Metadaten <a class="header-anchor" href="#erkennung-und-metadaten" aria-label="Permalink to &quot;Erkennung und Metadaten&quot;">​</a></h2><p>Nach jedem Import erkennt Anthology die Aufnahmen: über die ISRC, über den akustischen Fingerabdruck bei AcoustID (mit API-Schlüssel), sonst über eine Suche bei MusicBrainz nach Künstler und Titel. Treffer unterhalb der Gewissheit kommen in die Prüfliste. Ein täglicher Abgleich vergleicht erkannte Aufnahmen mit MusicBrainz; Änderungen an Werten, die jemand von Hand gesetzt hat, werden zu Konflikten.</p><h2 id="qualitatsanalyse" tabindex="-1">Qualitätsanalyse <a class="header-anchor" href="#qualitatsanalyse" aria-label="Permalink to &quot;Qualitätsanalyse&quot;">​</a></h2><p>Redaktion und Administratoren können unter <strong>Einstellungen</strong> die Qualitätsanalyse der ganzen Bibliothek starten. Sie analysiert das Spektrum jeder Datei einmal und speichert ihre <strong>tatsächliche Qualität</strong>. Importe und Bestellungen analysieren nur die Dateien, die sie vergleichen müssen.</p><h2 id="cover" tabindex="-1">Cover <a class="header-anchor" href="#cover" aria-label="Permalink to &quot;Cover&quot;">​</a></h2><p>Cover werden nach jedem Import geholt (eingebettete Bilder, Cover Art Archive). Einmal pro Installation holt ein Auftrag sie für die bestehende Bibliothek. Die Redaktion kann sie für ein Album oder die ganze Bibliothek erneut holen.</p><h2 id="auftrage" tabindex="-1">Aufträge <a class="header-anchor" href="#auftrage" aria-label="Permalink to &quot;Aufträge&quot;">​</a></h2><p>Jede lange Aufgabe ist ein Auftrag. Die Auftragsübersicht zeigt sie mit Fortschritt live; du kannst sie pausieren, fortsetzen oder abbrechen. <code>ANTHOLOGY_JOBS_THROTTLE</code> begrenzt, wie viele gleichzeitig laufen.</p>',13)])])}const m=n(r,[["render",s]]);export{g as __pageData,m as default};
